def transform(grid):
    """Mark background-colored cells that differ across repeated active row-blocks."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Split the non-background rows into separated pattern blocks.
    blocks = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        blocks.append((start, r))

    # Repeated blocks encode a base motif plus gaps/overlays. Mark only the
    # background cells wherever a block disagrees with the first matching block.
    if len(blocks) >= 2:
        base_start, base_end = blocks[0]
        base = grid[base_start:base_end]
        for start, end in blocks[1:]:
            if end - start != len(base):
                continue
            for dr in range(len(base)):
                for c in range(w):
                    if grid[start + dr][c] != base[dr][c]:
                        if grid[start + dr][c] == bg:
                            out[start + dr][c] = 1
                        if base[dr][c] == bg:
                            out[base_start + dr][c] = 1
    return out
